package br.com.equilibra.goal.api;
import br.com.equilibra.goal.application.FinancialGoalService; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/goals") @Tag(name="Financial goals") @SecurityRequirement(name="bearerAuth") public class FinancialGoalController {private final FinancialGoalService service;public FinancialGoalController(FinancialGoalService s){service=s;} @PostMapping public ResponseEntity<GoalDtos.Response> create(@RequestBody GoalDtos.Create r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@GetMapping public List<GoalDtos.Response> list(){return service.list();}@GetMapping("/{id}") public GoalDtos.Response get(@PathVariable String id){return service.get(id);}@PutMapping("/{id}") public GoalDtos.Response update(@PathVariable String id,@RequestBody GoalDtos.Update r){return service.update(id,r);}@PostMapping("/{id}/contributions") public GoalDtos.Response contribute(@PathVariable String id,@RequestBody GoalDtos.Contribution r){return service.contribute(id,r);}@PostMapping("/{id}/complete") public GoalDtos.Response complete(@PathVariable String id){return service.complete(id);}@PostMapping("/{id}/archive") public GoalDtos.Response archive(@PathVariable String id){return service.archive(id);}}
